//! Relay between the Workbench and the runtime (ADR-0003).
//!
//! The Host parses only the envelope (`jsonrpc`, `id`, `method`); params and results stay
//! opaque JSON and are validated by the runtime and the Workbench against
//! `packages/protocol`. The Workbench may call only methods in [`allowlist`], and the Host
//! answers reverse `host.*` calls itself.

// Generated by scripts/gen-allowlist.mjs; formatting is the generator's.
#[rustfmt::skip]
pub mod allowlist;
#[cfg(test)]
mod latency;
pub mod lines;

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;
use std::time::Duration;

use serde_json::{json, Value};
use tokio::io::{AsyncWrite, AsyncWriteExt};
use tokio::sync::{oneshot, watch, Mutex as AsyncMutex};

use crate::logging;

const MODULE: &str = "rpc_relay";

/// Largest message either side may send (ADR-0003, decision 7).
pub const MAX_MESSAGE_BYTES: usize = 4 * 1024 * 1024;

// JSON-RPC codes from ARCHITECTURE.md section 9.2.
pub const INVALID_REQUEST: i64 = -32600;
pub const METHOD_NOT_FOUND: i64 = -32601;
pub const APPLICATION_ERROR: i64 = -32000;

// JesutobitsError codes the Host produces. A test checks they exist in packages/protocol.
pub const CODE_METHOD_NOT_FOUND: &str = "rpc.method_not_found";
pub const CODE_METHOD_NOT_ALLOWED: &str = "rpc.method_not_allowed";
pub const CODE_MESSAGE_TOO_LARGE: &str = "rpc.message_too_large";
pub const CODE_TIMEOUT: &str = "rpc.timeout";
pub const CODE_UNAVAILABLE: &str = "runtime.unavailable";

/// A JSON-RPC error object whose `data` is a JesutobitsError, as the runtime sends them.
pub fn rpc_error(code: i64, error_code: &str, message: &str, retryable: bool) -> Value {
    json!({
        "code": code,
        "message": message,
        "data": { "code": error_code, "message": message, "retryable": retryable },
    })
}

pub fn unavailable(message: &str) -> Value {
    rpc_error(APPLICATION_ERROR, CODE_UNAVAILABLE, message, true)
}

type Reply = Result<Value, Value>;
type Writer = Box<dyn AsyncWrite + Send + Unpin>;
type EventSink = Box<dyn Fn(Value) + Send + Sync>;

/// One live stdio connection to a runtime process.
pub struct Connection {
    writer: AsyncMutex<Writer>,
    pending: Mutex<HashMap<String, oneshot::Sender<Reply>>>,
    next_id: AtomicU64,
    on_event: EventSink,
    /// True once the runtime's stdout has ended.
    closed: watch::Sender<bool>,
}

impl Connection {
    pub fn new(writer: Writer, on_event: EventSink) -> Self {
        Self {
            writer: AsyncMutex::new(writer),
            pending: Mutex::new(HashMap::new()),
            next_id: AtomicU64::new(1),
            on_event,
            closed: watch::channel(false).0,
        }
    }

    /// Sends a request and waits for its reply. `Err` holds a JSON-RPC error object.
    pub async fn call(&self, method: &str, params: Value, timeout: Duration) -> Reply {
        let id = format!("h-{}", self.next_id.fetch_add(1, Ordering::Relaxed));
        let (tx, rx) = oneshot::channel();
        self.pending.lock().unwrap().insert(id.clone(), tx);

        let request = json!({ "jsonrpc": "2.0", "id": id, "method": method, "params": params });
        if let Err(error) = self.send(&request).await {
            self.pending.lock().unwrap().remove(&id);
            return Err(error);
        }

        match tokio::time::timeout(timeout, rx).await {
            Ok(Ok(reply)) => reply,
            Ok(Err(_)) => Err(unavailable("The runtime stopped before replying")),
            Err(_) => {
                self.pending.lock().unwrap().remove(&id);
                let message = format!("{method} did not reply within {} ms", timeout.as_millis());
                Err(rpc_error(APPLICATION_ERROR, CODE_TIMEOUT, &message, true))
            }
        }
    }

    /// Routes one line from the runtime's stdout.
    pub async fn handle_line(&self, line: &[u8]) {
        let Ok(Value::Object(message)) = serde_json::from_slice::<Value>(line) else {
            logging::warn(MODULE, "dropping a runtime line that is not a JSON object");
            return;
        };
        let method = message.get("method").and_then(Value::as_str);
        match (method, message.get("id")) {
            (Some("event"), None) => {
                (self.on_event)(message.get("params").cloned().unwrap_or(Value::Null));
            }
            (Some(method), Some(id)) => {
                // Reverse calls: host.secrets.get, host.log and host.notify arrive with the
                // features that need them. Until then, and for any other name, refuse.
                let error = rpc_error(
                    METHOD_NOT_FOUND,
                    CODE_METHOD_NOT_FOUND,
                    &format!("The Host does not implement {method}"),
                    false,
                );
                let reply = json!({ "jsonrpc": "2.0", "id": id, "error": error });
                if let Err(error) = self.send(&reply).await {
                    logging::warn(
                        MODULE,
                        format!("could not answer reverse call {method}: {error}"),
                    );
                }
            }
            (Some(method), None) => {
                logging::warn(MODULE, format!("ignoring runtime notification {method}"))
            }
            (None, Some(id)) => {
                let Some(id) = id.as_str() else {
                    logging::warn(MODULE, "dropping a reply with a non-string id");
                    return;
                };
                let Some(tx) = self.pending.lock().unwrap().remove(id) else {
                    // Late reply to a call that already timed out.
                    return;
                };
                let reply = match (message.get("result"), message.get("error")) {
                    (Some(result), None) => Ok(result.clone()),
                    (None, Some(error)) => Err(error.clone()),
                    _ => Err(unavailable("The runtime sent a malformed reply")),
                };
                let _ = tx.send(reply);
            }
            (None, None) => {
                logging::warn(MODULE, "dropping a runtime message without method or id")
            }
        }
    }

    /// Fails every pending call; used when the runtime's stdout closes.
    pub fn close(&self) {
        self.pending.lock().unwrap().clear();
        self.closed.send_replace(true);
    }

    /// Resolves once the runtime's stdout has ended: the earliest sign that it is gone.
    pub async fn closed(&self) {
        let mut closed = self.closed.subscribe();
        let _ = closed.wait_for(|closed| *closed).await;
    }

    async fn send(&self, message: &Value) -> Result<(), Value> {
        let mut line = serde_json::to_vec(message).expect("serde_json::Value always serialises");
        if line.len() > MAX_MESSAGE_BYTES {
            let text = format!("Message exceeds {MAX_MESSAGE_BYTES} bytes");
            return Err(rpc_error(
                INVALID_REQUEST,
                CODE_MESSAGE_TOO_LARGE,
                &text,
                false,
            ));
        }
        line.push(b'\n');
        let mut writer = self.writer.lock().await;
        let written = async {
            writer.write_all(&line).await?;
            writer.flush().await
        };
        written
            .await
            .map_err(|error| unavailable(&format!("Could not write to the runtime: {error}")))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use tokio::io::{duplex, AsyncBufReadExt, BufReader};

    /// A connection whose "runtime" end is returned as a line reader plus writer.
    fn connect() -> (
        Arc<Connection>,
        BufReader<tokio::io::DuplexStream>,
        Arc<Mutex<Vec<Value>>>,
    ) {
        let (host_end, runtime_end) = duplex(64 * 1024);
        let events = Arc::new(Mutex::new(Vec::new()));
        let sink = events.clone();
        let connection = Arc::new(Connection::new(
            Box::new(host_end),
            Box::new(move |event| sink.lock().unwrap().push(event)),
        ));
        (connection, BufReader::new(runtime_end), events)
    }

    async fn next_message(reader: &mut BufReader<tokio::io::DuplexStream>) -> Value {
        let mut line = String::new();
        reader.read_line(&mut line).await.unwrap();
        serde_json::from_str(&line).unwrap()
    }

    #[tokio::test]
    async fn correlates_replies_with_calls() {
        let (connection, mut runtime, _) = connect();
        let caller = connection.clone();
        let call = tokio::spawn(async move {
            caller
                .call("runtime.ping", json!({}), Duration::from_secs(5))
                .await
        });

        let request = next_message(&mut runtime).await;
        assert_eq!(request["method"], "runtime.ping");
        let id = request["id"].as_str().unwrap().to_owned();
        let reply = json!({ "jsonrpc": "2.0", "id": id, "result": { "uptimeMs": 7 } });
        connection.handle_line(reply.to_string().as_bytes()).await;

        assert_eq!(call.await.unwrap().unwrap(), json!({ "uptimeMs": 7 }));
    }

    #[tokio::test]
    async fn passes_error_replies_through_unchanged() {
        let (connection, mut runtime, _) = connect();
        let caller = connection.clone();
        let call = tokio::spawn(async move {
            caller
                .call("runtime.ping", json!({}), Duration::from_secs(5))
                .await
        });
        let id = next_message(&mut runtime).await["id"].clone();
        let error = rpc_error(APPLICATION_ERROR, "runtime.not_initialized", "x", false);
        let reply = json!({ "jsonrpc": "2.0", "id": id, "error": error });
        connection.handle_line(reply.to_string().as_bytes()).await;

        assert_eq!(call.await.unwrap().unwrap_err(), error);
    }

    #[tokio::test]
    async fn times_out_and_ignores_the_late_reply() {
        let (connection, mut runtime, _) = connect();
        let error = connection
            .call("runtime.ping", json!({}), Duration::from_millis(20))
            .await
            .unwrap_err();
        assert_eq!(error["data"]["code"], CODE_TIMEOUT);

        let id = next_message(&mut runtime).await["id"].clone();
        let late = json!({ "jsonrpc": "2.0", "id": id, "result": {} });
        connection.handle_line(late.to_string().as_bytes()).await;
    }

    #[tokio::test]
    async fn forwards_events_to_the_sink() {
        let (connection, _, events) = connect();
        let event = json!({ "jsonrpc": "2.0", "method": "event", "params": { "seq": 1, "type": "runtime.warning" } });
        connection.handle_line(event.to_string().as_bytes()).await;
        assert_eq!(events.lock().unwrap()[0]["seq"], 1);
    }

    #[tokio::test]
    async fn refuses_reverse_calls_it_does_not_implement() {
        let (connection, mut runtime, _) = connect();
        let call =
            json!({ "jsonrpc": "2.0", "id": "r-1", "method": "host.secrets.get", "params": {} });
        connection.handle_line(call.to_string().as_bytes()).await;

        let reply = next_message(&mut runtime).await;
        assert_eq!(reply["id"], "r-1");
        assert_eq!(reply["error"]["code"], METHOD_NOT_FOUND);
    }

    #[tokio::test]
    async fn closed_resolves_after_close() {
        let (connection, _runtime, _) = connect();
        let waiter = connection.clone();
        let closed = tokio::spawn(async move { waiter.closed().await });
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert!(!closed.is_finished());
        connection.close();
        tokio::time::timeout(Duration::from_secs(1), closed)
            .await
            .expect("closed() resolves")
            .unwrap();
    }

    #[tokio::test]
    async fn closing_fails_pending_calls() {
        let (connection, _runtime, _) = connect();
        let caller = connection.clone();
        let call = tokio::spawn(async move {
            caller
                .call("runtime.ping", json!({}), Duration::from_secs(5))
                .await
        });
        tokio::time::sleep(Duration::from_millis(20)).await;
        connection.close();
        assert_eq!(
            call.await.unwrap().unwrap_err()["data"]["code"],
            CODE_UNAVAILABLE
        );
    }

    /// Contract test (TESTING_STRATEGY.md section 2): the generated allowlist matches
    /// packages/protocol, and every code the Host emits exists there.
    #[test]
    fn allowlist_and_error_codes_match_the_protocol() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../../packages/protocol/generated/methods.json"
        );
        let methods: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        let names = |key: &str| -> Vec<String> {
            methods[key]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().to_owned())
                .collect()
        };
        assert_eq!(names("workbench"), allowlist::WORKBENCH_METHODS);
        assert_eq!(names("host"), allowlist::HOST_METHODS);
        assert_eq!(methods["protocolVersion"], allowlist::PROTOCOL_VERSION);

        let codes = names("errorCodes");
        for code in [
            CODE_METHOD_NOT_FOUND,
            CODE_METHOD_NOT_ALLOWED,
            CODE_MESSAGE_TOO_LARGE,
            CODE_TIMEOUT,
            CODE_UNAVAILABLE,
            crate::settings_store::CODE_INVALID_SETTINGS,
            crate::settings_store::CODE_READ_ONLY,
            crate::settings_store::CODE_WRITE_FAILED,
            crate::settings_store::CODE_SETTINGS_NEWER,
            crate::settings_store::CODE_SETTINGS_CORRUPT,
            crate::dialogs::CODE_DIALOG_OPEN,
        ] {
            assert!(
                codes.iter().any(|c| c == code),
                "{code} is missing from packages/protocol"
            );
        }
    }
}
